package cc.ocage.plugin;

import com.google.gson.annotations.SerializedName;
import java.util.List;
import java.util.Map;

/**
 * Request and response bodies of the bot's /plugin/* routes. The bot's
 * openapi.json ("Plugin" tag) is the source of truth for these shapes.
 */
final class Api
{
	private Api()
	{
	}

	static final class LinkRequest
	{
		final String code;
		@SerializedName("account_hash")
		final String accountHash;
		final String rsn;

		LinkRequest(String code, String accountHash, String rsn)
		{
			this.code = code;
			this.accountHash = accountHash;
			this.rsn = rsn;
		}
	}

	static final class LinkResponse
	{
		String token;
		String rsn;
		@SerializedName("display_name")
		String displayName;
	}

	/** GET /plugin/config: what to report. */
	static final class Rules
	{
		@SerializedName("min_value")
		long minValue;
		@SerializedName("item_ids")
		List<Integer> itemIds;
		@SerializedName("clog_item_ids")
		List<Integer> clogItemIds;
		List<RulesEvent> events;
		/** Active bingo events the player is on a team for (older bots don't send it). */
		List<Bingo> bingo;
		@SerializedName("refresh_seconds")
		int refreshSeconds;
	}

	static final class RulesEvent
	{
		int id;
		String name;
		List<String> bosses;
	}

	static final class Bingo
	{
		String event;
		String team;
		/** The event password (null if the event has none). */
		String password;
		@SerializedName("end_date")
		String endDate;
		/** The board's Item List: these are reported, with a screenshot. */
		@SerializedName("item_names")
		List<String> itemNames;
	}

	static final class Item
	{
		final int id;
		final int quantity;
		final long price;
		/** For the bot's /plugin_admin log only; the bot matches items by id. */
		final String name;

		Item(int id, int quantity, long price, String name)
		{
			this.id = id;
			this.quantity = quantity;
			this.price = price;
			this.name = name;
		}
	}

	/** One report (kill, loot, pet, clog, ca). {@code id} makes a resent report a harmless duplicate. */
	static final class Report
	{
		final String id;
		final String type;
		@SerializedName("occurred_at")
		final String occurredAt;
		final String source;
		final Integer kc;
		final List<Item> items;
		/** Loot only: RuneLite's loot type, lower-case ("npc", "event" for clues and chests, ...). */
		@SerializedName("loot_type")
		final String lootType;
		/** Loot only: the whole loot's GE value, items the rules filter out included. */
		@SerializedName("total_value")
		final Long totalValue;
		/** Loot only: a screenshot of it was taken, to upload if the bot asks (a bingo drop). */
		final Boolean screenshot;

		private Report(String id, String type, String occurredAt, String source, Integer kc, List<Item> items,
			String lootType, Long totalValue, Boolean screenshot)
		{
			this.id = id;
			this.type = type;
			this.occurredAt = occurredAt;
			this.source = source;
			this.kc = kc;
			this.items = items;
			this.lootType = lootType;
			this.totalValue = totalValue;
			this.screenshot = screenshot;
		}

		static Report kill(String id, String occurredAt, String boss, int kc)
		{
			return new Report(id, "kill", occurredAt, boss, kc, null, null, null, null);
		}

		/** A pet; {@code name} is null when the game didn't say which (a duplicate pet). */
		static Report pet(String id, String occurredAt, String name)
		{
			return new Report(id, "pet", occurredAt, name, null, null, null, null, null);
		}

		/** A new collection-log item (the game's "New item added to your collection log" message). */
		static Report clog(String id, String occurredAt, String name)
		{
			return new Report(id, "clog", occurredAt, name, null, null, null, null, null);
		}

		static Report loot(String id, String occurredAt, String source, String lootType, long totalValue, List<Item> items,
			boolean screenshot)
		{
			return new Report(id, "loot", occurredAt, source, null, items, lootType, totalValue, screenshot ? true : null);
		}

		/** The highest Combat Achievements tier the account has reached ("None" if none yet). */
		static Report ca(String id, String occurredAt, String tier)
		{
			return new Report(id, "ca", occurredAt, tier, null, null, null, null, null);
		}

		/** This loot report with only {@code kept} items (the rest of its fields unchanged). */
		Report withItems(List<Item> kept)
		{
			return new Report(id, type, occurredAt, source, kc, kept, lootType, totalValue, screenshot);
		}
	}

	static final class ReportBatch
	{
		final String rsn;
		final List<Report> events;

		ReportBatch(String rsn, List<Report> events)
		{
			this.rsn = rsn;
			this.events = events;
		}
	}

	static final class IngestResponse
	{
		int accepted;
		int duplicates;
		int ignored;
		List<Counted> counted;
		/** Report ids whose screenshot the bot wants (older bots don't send it). */
		List<String> screenshots;
		/** Chat lines for the player, e.g. a new CA tier (older bots don't send it). */
		List<String> notices;
	}

	static final class ScreenshotResponse
	{
		/** True: the bot will post it and submit the drop. False: it wasn't waiting for one (nothing to do). */
		boolean accepted;
	}

	static final class Counted
	{
		String event;
		String boss;
		Integer kc;
		@SerializedName("item_id")
		Integer itemId;
		Integer quantity;
	}

	/** GET /plugin/me: the side panel's standings. */
	static final class Me
	{
		String rsn;
		@SerializedName("display_name")
		String displayName;
		List<MeEvent> events;
		/** Active bingos the player is on a team for (older bots don't send it). */
		List<MeBingo> bingo;
		/** When to ask again: shorter while a bingo is on (older bots don't send it). */
		@SerializedName("refresh_seconds")
		Integer refreshSeconds;
	}

	static final class MeBingo
	{
		String event;
		String team;
		/** The team's rank; tied teams share one. */
		Integer rank;
		double points;
		@SerializedName("tiles_verified")
		int tilesVerified;
		@SerializedName("end_date")
		String endDate;
		List<MeBingoTeam> leaderboard;
	}

	static final class MeBingoTeam
	{
		int rank;
		String team;
		double points;
		@SerializedName("tiles_verified")
		int tilesVerified;
	}

	static final class MeEvent
	{
		String name;
		/** Every boss the event tracks, in order (older bots don't send it). */
		List<String> bosses;
		@SerializedName("end_date")
		String endDate;
		int kc;
		@SerializedName("kc_by_boss")
		Map<String, Integer> kcByBoss;
		@SerializedName("kc_rank")
		Integer kcRank;
		@SerializedName("unique_drops")
		int uniqueDrops;
		/** The unique items gained, by name (older bots don't send it). */
		List<MeDrop> drops;
		@SerializedName("drops_rank")
		Integer dropsRank;
	}

	static final class MeDrop
	{
		@SerializedName("item_id")
		int itemId;
		String name;
	}

	static final class Error
	{
		String detail;
		/** Set on the few errors the plugin must act on, e.g. "plugin_banned". */
		String code;
	}
}

package cc.ocage.plugin;

import java.io.InputStream;
import java.util.Properties;
import lombok.extern.slf4j.Slf4j;

/**
 * Which Ocage bot API this client talks to: the address baked in at build
 * time ({@code ./gradlew run -PocageApiUrl=...} or {@code shadowJar
 * -PocageApiUrl=...}, for the test server), else production,
 * {@link #PRODUCTION}. The Plugin Hub builds with its own build.gradle
 * ({@code build=standard}), which leaves the address unfilled, so every Hub
 * release uses production, and nothing on the player's PC (an
 * environment variable, a Java property) can point it anywhere else.
 * A key only works on the server that issued it, so each server keeps its own
 * key (see {@link OcagePlugin#keyName()}).
 */
@Slf4j
final class ApiUrl
{
	static final String PRODUCTION = "https://api.ocage.cc";

	private ApiUrl()
	{
	}

	static String resolve()
	{
		String url = buildDefault();
		if (url == null || url.trim().isEmpty())
		{
			url = PRODUCTION;
		}
		url = url.trim();
		while (url.endsWith("/"))
		{
			url = url.substring(0, url.length() - 1);
		}
		if (!url.startsWith("https://") && !url.startsWith("http://localhost") && !url.startsWith("http://127.0.0.1"))
		{
			// The key travels in every request: never send it in the clear.
			log.warn("Ignoring Ocage API URL {} — only https:// (or localhost) is allowed", url);
			url = PRODUCTION;
		}
		return url;
	}

	static boolean isProduction(String url)
	{
		return PRODUCTION.equals(url);
	}

	private static String buildDefault()
	{
		try (InputStream in = ApiUrl.class.getResourceAsStream("ocage-build.properties"))
		{
			if (in == null)
			{
				return null;
			}
			Properties properties = new Properties();
			properties.load(in);
			String value = properties.getProperty("apiUrl");
			// An unfiltered resource (e.g. run straight from an IDE) still says ${...}.
			return value == null || value.contains("${") ? null : value;
		}
		catch (Exception e)
		{
			log.debug("Couldn't read ocage-build.properties", e);
			return null;
		}
	}
}

package cc.ocage.plugin;

/**
 * What bingo screenshots hide of the chat (the same choices as the Dink
 * plugin). Labels are short on purpose: RuneLite's settings page puts the
 * dropdown beside the setting's name, sized to the longest label, so a long
 * one squeezes the name to "..".
 */
public enum ChatPrivacy
{
	HIDE_NONE("Show all"),
	HIDE_SPLIT_PM("Hide PMs"),
	HIDE_ALL("Hide all");

	private final String label;

	ChatPrivacy(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package cc.ocage.plugin;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The bot's /plugin/* routes. Every call is asynchronous (OkHttp's own
 * threads); callbacks run there too, never on the client thread, so
 * callers hop to the client thread or Swing thread themselves.
 */
@Slf4j
final class OcageClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType JPEG = MediaType.parse("image/jpeg");

	interface Result<T>
	{
		void ok(T value);

		void fail(Failure failure);
	}

	/** Why a call failed. */
	static final class Failure
	{
		/** The bot's error code for a banned player (see the bot's BingoError.code). */
		static final String BANNED = "plugin_banned";

		/** HTTP status, or 0 when the server couldn't be reached. */
		final int status;
		/** The bot's machine-readable error code, if it sent one. */
		final String code;
		/** What to show the player. */
		final String message;

		Failure(int status, String code, String message)
		{
			this.status = status;
			this.code = code;
			this.message = message;
		}

		boolean banned()
		{
			return status == 403 && BANNED.equals(code);
		}

		/** Worth retrying later: the server was unreachable, busy or broken. */
		boolean retryable()
		{
			return status == 0 || status == 429 || status >= 500;
		}
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final String baseUrl;
	private final String userAgent;

	OcageClient(OkHttpClient http, Gson gson, String baseUrl, String version)
	{
		this.http = http;
		this.gson = gson;
		this.baseUrl = baseUrl;
		this.userAgent = "Ocage-RuneLite-Plugin/" + version;
	}

	String baseUrl()
	{
		return baseUrl;
	}

	void link(Api.LinkRequest body, Result<Api.LinkResponse> result)
	{
		send(request("/plugin/link", null, null).post(json(body)).build(), Api.LinkResponse.class, result);
	}

	void rules(String key, String accountHash, Result<Api.Rules> result)
	{
		send(request("/plugin/config", key, accountHash).get().build(), Api.Rules.class, result);
	}

	void report(String key, String accountHash, Api.ReportBatch batch, Result<Api.IngestResponse> result)
	{
		send(request("/plugin/events", key, accountHash).post(json(batch)).build(), Api.IngestResponse.class, result);
	}

	void me(String key, String accountHash, Result<Api.Me> result)
	{
		send(request("/plugin/me", key, accountHash).get().build(), Api.Me.class, result);
	}

	void screenshot(String key, String accountHash, String reportId, byte[] jpeg, Result<Api.ScreenshotResponse> result)
	{
		RequestBody body = RequestBody.create(JPEG, jpeg);
		send(request("/plugin/screenshots/" + reportId, key, accountHash).post(body).build(), Api.ScreenshotResponse.class, result);
	}

	void unlink(String key, String accountHash, Result<Void> result)
	{
		send(request("/plugin/token", key, accountHash).delete().build(), Void.class, result);
	}

	private Request.Builder request(String path, String key, String accountHash)
	{
		HttpUrl url = HttpUrl.parse(baseUrl + path);
		Request.Builder builder = new Request.Builder().url(url).header("User-Agent", userAgent);
		if (key != null)
		{
			builder.header("Authorization", "Bearer " + key).header("X-Account-Hash", accountHash);
		}
		return builder;
	}

	private RequestBody json(Object body)
	{
		return RequestBody.create(JSON, gson.toJson(body));
	}

	private <T> void send(Request request, Class<T> type, Result<T> result)
	{
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Ocage API unreachable: {}", request.url(), e);
				result.fail(new Failure(0, null, "Couldn't reach the Ocage server."));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					String text = body == null ? "" : body.string();
					if (!response.isSuccessful())
					{
						result.fail(failure(text, response.code()));
						return;
					}
					result.ok(type == Void.class ? null : gson.fromJson(text, type));
				}
				catch (IOException | JsonParseException e)
				{
					log.warn("Bad response from Ocage API {}", request.url(), e);
					result.fail(new Failure(response.code(), null, "The Ocage server sent something unexpected."));
				}
			}
		});
	}

	private Failure failure(String text, int status)
	{
		try
		{
			Api.Error error = gson.fromJson(text, Api.Error.class);
			if (error != null && error.detail != null)
			{
				return new Failure(status, error.code, error.detail);
			}
		}
		catch (JsonParseException ignored)
		{
			// FastAPI validation errors (422) have a list, not a string, in "detail".
		}
		return new Failure(status, null, "The Ocage server said no (HTTP " + status + ").");
	}
}

package cc.ocage.plugin;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(OcageConfig.GROUP)
public interface OcageConfig extends Config
{
	String GROUP = "ocage";

	@ConfigItem(
		keyName = "countedMessages",
		name = "Show counted drops",
		description = "Show a chat message when a kill or drop counts toward an Ocage event, "
			+ "or you reach a new Combat Achievements tier",
		position = 1
	)
	default boolean countedMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bingoUpdates",
		name = "Bingo standing updates",
		description = "Show a chat message when your team's bingo points or rank change",
		position = 4
	)
	default boolean bingoUpdates()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bingoOverlay",
		name = "Show bingo overlay",
		description = "During a bingo, show the event, your team and the event password on screen. "
			+ "Screenshots of bingo drops always include it.",
		position = 2
	)
	default boolean bingoOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bingoScreenshots",
		name = "Screenshot bingo drops",
		description = "Upload a screenshot of a drop that counts for a bingo, as its proof. "
			+ "It shows your game screen; see 'Screenshot chat' for what's hidden. "
			+ "Off (the default): the drop is still submitted, without a picture.",
		// Plugin Hub rule: a setting that sends data to a third-party server is opt-in, with this warning.
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		position = 3
	)
	default boolean bingoScreenshots()
	{
		return false;
	}

	@ConfigItem(
		keyName = "chatPrivacy",
		name = "Screenshot chat",
		description = "What bingo screenshots hide. Hide PMs: private messages shown above the chat box "
			+ "(the game's 'Split friends private chat' setting). Hide all: the chat box too. "
			+ "The chat may flicker for a moment while the screenshot is taken.",
		position = 5
	)
	default ChatPrivacy chatPrivacy()
	{
		return ChatPrivacy.HIDE_SPLIT_PM;
	}
}

package cc.ocage.plugin;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * During a bingo: the event, the player's team, the event password and the
 * time, on the game screen. Every screenshot of the game then shows them, so
 * a screenshot is its own proof. Shown while the player has it turned on,
 * and always in the frame the plugin screenshots.
 */
class OcageOverlay extends OverlayPanel
{
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm 'UTC'");
	private static final Color TITLE = new Color(0x1f, 0xc7, 0xb4);

	private final OcagePlugin plugin;

	@Inject
	OcageOverlay(OcagePlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<Api.Bingo> bingo = plugin.activeBingo();
		if (bingo.isEmpty() || !plugin.showBingoOverlay())
		{
			return null;
		}
		panelComponent.getChildren().add(TitleComponent.builder().text("Ocage Bingo").color(TITLE).build());
		for (Api.Bingo entry : bingo)
		{
			line("Event", entry.event);
			line("Team", entry.team);
			if (entry.password != null && !entry.password.isEmpty())
			{
				line("Password", entry.password);
			}
		}
		line("Time", ZonedDateTime.now(ZoneOffset.UTC).format(TIME));
		return super.render(graphics);
	}

	private void line(String left, String right)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(left).right(right == null ? "" : right).build());
	}
}

package cc.ocage.plugin;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.UIManager;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * The Ocage sidebar: the clan banner, linking with a /plugin link code, then
 * your standing in active clan events. Every method runs on the Swing thread
 * (the plugin calls them through SwingUtilities.invokeLater).
 *
 * <p>Layout: one left-aligned column. Text is shown in read-only text areas
 * that wrap at word boundaries to whatever width the sidebar gives them —
 * HTML labels don't wrap reliably (they measure text differently from how
 * it's drawn, and RuneLite's font differs again), which cut lines off at the
 * right edge. Every row is left-aligned: a vertical BoxLayout otherwise
 * centres panels and left-aligns labels, pushing text off to one side.</p>
 */
@Slf4j
class OcagePanel extends PluginPanel
{
	private final OcagePlugin plugin;
	private final JTextArea server;
	private final JTextArea status = text("", null);
	private final JTextArea error = text("", ColorScheme.PROGRESS_ERROR_COLOR);
	private final JTextField codeField = new JTextField();
	private final JButton linkButton = new JButton("Link");
	private final JButton unlinkButton = new JButton("Unlink");
	private final JButton refreshButton = new JButton("Refresh");
	private final JPanel linkForm = new JPanel(new BorderLayout(0, 4));
	private final JPanel standings = column();
	/** Whether each section is open, kept across refreshes (all open at first). */
	private boolean bingoOpen = true;
	private boolean bossOpen = true;
	/** The width the text was last wrapped at. */
	private int laidOutWidth = -1;

	OcagePanel(OcagePlugin plugin, String serverUrl, boolean production)
	{
		this.plugin = plugin;
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		JPanel top = column();
		top.add(row(banner()));
		// Never let a tester mistake the test server for the real one.
		server = text("TEST server: " + serverUrl, ColorScheme.PROGRESS_INPROGRESS_COLOR);
		server.setVisible(!production);
		top.add(row(server));
		top.add(row(status));
		top.add(row(error));

		linkForm.add(text("In Discord, run /plugin link and paste the code:", null), BorderLayout.NORTH);
		linkForm.add(codeField, BorderLayout.CENTER);
		linkForm.add(linkButton, BorderLayout.SOUTH);
		linkForm.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		linkButton.addActionListener(e ->
		{
			String code = codeField.getText().trim();
			if (!code.isEmpty())
			{
				setError(null);
				linkButton.setEnabled(false);
				plugin.link(code);
			}
		});
		top.add(row(linkForm));

		JPanel buttons = new JPanel(new GridLayout(1, 2, 4, 0));
		buttons.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		buttons.add(refreshButton);
		buttons.add(unlinkButton);
		refreshButton.addActionListener(e -> plugin.refresh());
		unlinkButton.addActionListener(e -> plugin.unlink());
		top.add(row(buttons));

		add(top, BorderLayout.NORTH);
		add(standings, BorderLayout.CENTER);
		addComponentListener(new ComponentAdapter()
		{
			@Override
			public void componentResized(ComponentEvent e)
			{
				if (getWidth() != laidOutWidth)
				{
					laidOutWidth = getWidth();
					relayout();
				}
			}
		});
		showLoggedOut();
	}

	/**
	 * A wrapping text area only knows its height once the first layout pass
	 * has given it a width, and Swing caches that first answer: so lay out,
	 * then forget the cached sizes and lay out again.
	 */
	private void relayout()
	{
		revalidate();
		SwingUtilities.invokeLater(() ->
		{
			invalidateTree(this);
			revalidate();
			repaint();
		});
	}

	private static void invalidateTree(Component component)
	{
		component.invalidate();
		if (component instanceof Container)
		{
			for (Component child : ((Container) component).getComponents())
			{
				invalidateTree(child);
			}
		}
	}

	// -- Building blocks -----------------------------------------------------------

	/** The clan's animated banner (the website's), centred; the name if it can't be loaded. */
	private static JLabel banner()
	{
		JLabel label = new JLabel();
		byte[] gif = null;
		// getResourceAsStream, not getResource: a Hub plugin runs from its jar (Plugin Hub README).
		try (InputStream in = OcagePanel.class.getResourceAsStream("banner.gif"))
		{
			gif = in == null ? null : in.readAllBytes();
		}
		catch (IOException e)
		{
			log.debug("Couldn't load the Ocage banner", e);
		}
		if (gif != null)
		{
			// ImageIcon from the bytes keeps a GIF animated.
			label.setIcon(new ImageIcon(gif));
		}
		else
		{
			label.setText("Ocage");
			label.setFont(label.getFont().deriveFont(16f));
		}
		label.setHorizontalAlignment(SwingConstants.CENTER);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		return label;
	}

	/** Read-only text that wraps at word boundaries to the width it's given. */
	private static JTextArea text(String value, Color color)
	{
		JTextArea area = new JTextArea(value);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setEditable(false);
		area.setFocusable(false);
		area.setOpaque(false);
		area.setBorder(null);
		// A tiny preferred width: the layout stretches it to the sidebar's
		// width, and it wraps there, instead of widening the sidebar.
		area.setColumns(1);
		area.setFont(UIManager.getFont("Label.font"));
		area.setForeground(color != null ? color : UIManager.getColor("Label.foreground"));
		return area;
	}

	private static JTextArea bold(String value)
	{
		JTextArea area = text(value, null);
		area.setFont(area.getFont().deriveFont(Font.BOLD));
		return area;
	}

	/** Indented, e.g. a boss or a drop under its heading. */
	private static JComponent indented(JComponent component)
	{
		component.setBorder(BorderFactory.createEmptyBorder(0, 10, 0, 0));
		return component;
	}

	private static JPanel column()
	{
		JPanel column = new JPanel();
		column.setLayout(new BoxLayout(column, BoxLayout.Y_AXIS));
		column.setOpaque(false);
		return column;
	}

	/**
	 * One full-width, left-aligned row of a column: a vertical BoxLayout
	 * lines children up by their alignmentX, so every row gets the same.
	 */
	private static JComponent row(JComponent component)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.add(component, BorderLayout.CENTER);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		return row;
	}

	// -- States --------------------------------------------------------------------

	void showLoggedOut()
	{
		status.setText("Log in to the game to link or see your events.");
		setLinkedControls(false);
		linkForm.setVisible(false);
		standings.removeAll();
		relayout();
	}

	void showNotLinked()
	{
		status.setText("This account isn't linked yet.");
		setLinkedControls(false);
		standings.removeAll();
		relayout();
	}

	void showLinked(String rsn)
	{
		status.setText("Linked as " + rsn);
		codeField.setText("");
		setError(null);
		setLinkedControls(true);
		relayout();
	}

	void showError(String message)
	{
		setError(message);
		linkButton.setEnabled(true);
		relayout();
	}

	private void setError(String message)
	{
		error.setText(message == null ? "" : message);
		error.setVisible(message != null && !message.isEmpty());
	}

	void showStandings(Api.Me me)
	{
		showLinked(me.displayName.equals(me.rsn) ? me.rsn : me.rsn + " (" + me.displayName + ")");
		standings.removeAll();
		List<JComponent> bingoCards = new ArrayList<>();
		if (me.bingo != null)
		{
			for (Api.MeBingo bingo : me.bingo)
			{
				bingoCards.add(bingoCard(bingo));
			}
		}
		List<JComponent> bossCards = new ArrayList<>();
		if (me.events != null)
		{
			for (Api.MeEvent event : me.events)
			{
				bossCards.add(eventCard(event));
			}
		}
		if (bingoCards.isEmpty() && bossCards.isEmpty())
		{
			standings.add(row(text("No active events right now.", null)));
		}
		if (!bingoCards.isEmpty())
		{
			standings.add(row(section("Bingo", bingoCards, bingoOpen, open -> bingoOpen = open)));
		}
		if (!bossCards.isEmpty())
		{
			standings.add(row(section("Boss events", bossCards, bossOpen, open -> bossOpen = open)));
		}
		relayout();
	}

	/**
	 * A collapsible section: a header (an arrow and "Bingo (2)") that opens and closes
	 * the cards under it. Whether it's open is remembered across refreshes.
	 */
	private JComponent section(String title, List<JComponent> cards, boolean open, Consumer<Boolean> remember)
	{
		JPanel body = column();
		for (JComponent card : cards)
		{
			body.add(row(card));
		}
		body.setVisible(open);

		JLabel header = new JLabel();
		header.setFont(header.getFont().deriveFont(Font.BOLD));
		header.setOpaque(true);
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		String label = title + " (" + cards.size() + ")";
		header.setText(label);
		header.setIcon(new Arrow(open));
		header.setIconTextGap(6);
		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				boolean nowOpen = !body.isVisible();
				body.setVisible(nowOpen);
				header.setIcon(new Arrow(nowOpen));
				remember.accept(nowOpen);
				relayout();
			}
		});

		JPanel section = column();
		JComponent headerRow = row(header);
		headerRow.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		section.add(headerRow);
		section.add(row(body));
		section.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		return section;
	}

	/** A small open (pointing down) or closed (pointing right) triangle — drawn, not a font glyph. */
	private static final class Arrow implements Icon
	{
		private static final int SIZE = 8;
		private final boolean open;

		Arrow(boolean open)
		{
			this.open = open;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(c.getForeground());
			if (open)
			{
				g2.fillPolygon(new int[]{x, x + SIZE, x + SIZE / 2}, new int[]{y + 2, y + 2, y + SIZE - 1}, 3);
			}
			else
			{
				g2.fillPolygon(new int[]{x + 1, x + SIZE - 2, x + 1}, new int[]{y, y + SIZE / 2, y + SIZE}, 3);
			}
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return SIZE;
		}
	}

	/** A bingo: the player's team, its rank and points, and the leaderboard. */
	private JPanel bingoCard(Api.MeBingo bingo)
	{
		JPanel lines = column();
		lines.add(row(bold(bingo.event)));
		String standing = bingo.rank == null ? "" : ", " + OcagePlugin.ordinal(bingo.rank);
		lines.add(row(text("Your team: " + bingo.team + standing + " - " + OcagePlugin.points(bingo.points), null)));
		if (bingo.leaderboard != null && !bingo.leaderboard.isEmpty())
		{
			lines.add(row(text("Leaderboard", null)));
			for (Api.MeBingoTeam team : bingo.leaderboard)
			{
				boolean mine = team.team.equals(bingo.team);
				String line = team.rank + ". " + team.team + " - " + OcagePlugin.points(team.points)
					+ " (" + team.tilesVerified + (team.tilesVerified == 1 ? " tile)" : " tiles)");
				lines.add(row(indented(mine ? bold(line) : text(line, null))));
			}
		}
		if (bingo.endDate != null)
		{
			lines.add(row(text("Ends " + bingo.endDate + " UTC", null)));
		}
		return card(lines);
	}

	private JPanel eventCard(Api.MeEvent event)
	{
		JPanel lines = column();
		lines.add(row(bold(event.name)));
		lines.add(row(text("KC gained: " + event.kc + rank(event.kcRank), null)));
		// Every tracked boss, even one, even at 0 — so it's clear what counts.
		// An older bot sends no boss list: fall back to the bosses with KC.
		Map<String, Integer> kcByBoss = event.kcByBoss != null ? event.kcByBoss : new LinkedHashMap<>();
		List<String> bosses = event.bosses != null ? event.bosses : new ArrayList<>(kcByBoss.keySet());
		for (String boss : bosses)
		{
			lines.add(row(indented(text(boss + ": " + kcByBoss.getOrDefault(boss, 0), null))));
		}
		lines.add(row(text("Unique drops: " + event.uniqueDrops + rank(event.dropsRank), null)));
		if (event.drops != null)
		{
			for (Api.MeDrop drop : event.drops)
			{
				lines.add(row(indented(text(drop.name, null))));
			}
		}
		if (event.endDate != null)
		{
			lines.add(row(text("Ends " + event.endDate + " UTC", null)));
		}
		return card(lines);
	}

	/** A dark card around one event's lines, with a gap below it. */
	private static JPanel card(JPanel lines)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.add(lines, BorderLayout.CENTER);
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setOpaque(false);
		wrapper.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		wrapper.add(card);
		return wrapper;
	}

	private void setLinkedControls(boolean linked)
	{
		linkForm.setVisible(!linked);
		linkButton.setEnabled(true);
		unlinkButton.setVisible(linked);
		refreshButton.setVisible(linked);
	}

	private static String rank(Integer rank)
	{
		return rank == null ? "" : " (#" + rank + ")";
	}
}

